        'Isafjordur',
        66.0447,
        -23.125,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เวสต์ฟยอร์ด (ไอซ์แลนด์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว นอร์สโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Westfjords (Iceland), serving as the spiritual heart of ancestral นอร์สโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เวสต์ฟยอร์ด (ไอซ์แลนด์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Westfjords (Iceland), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน อีซาฟยอร์ดูร์',
        'Remove footwear and maintain silence within the inner terrace of Isafjordur.',
        'https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg","title":"เทวสถานศรัทธาแห่งแสงธรรม อีซาฟยอร์ดูร์ (นอร์สโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=KsnE0OGg2tk","title":"ตำนาน ปูชนียสถานศักดิ์สิทธิ์และบารมีพระบรมธาตุ","thumbnail":"https://i.ytimg.com/vi/KsnE0OGg2tk/hqdefault.jpg"}]'
      );

