      ) VALUES (
        'pin-sacred-notodden-15-142',
        'อารามโบราณพิทักษ์ผืนป่า นอต็อดเดน (ไวกิ้งนอร์ส)',
        'The Sacred Mountain Hermitage of Notodden (ไวกิ้งนอร์ส)',
        'sacred',
        'เทเลมาร์ก (นอร์เวย์)',
        'Telemark (Norway)',
        'นอต็อดเดน',
        'Notodden',
        59.5444,
        9.3036,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน เทเลมาร์ก (นอร์เวย์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ไวกิ้งนอร์ส เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Telemark (Norway), serving as the spiritual heart of ancestral ไวกิ้งนอร์ส heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค เทเลมาร์ก (นอร์เวย์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Telemark (Norway), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน นอต็อดเดน',
        'Remove footwear and maintain silence within the inner terrace of Notodden.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"อารามโบราณพิทักษ์ผืนป่า นอต็อดเดน (ไวกิ้งนอร์ส)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

