        'Rooted in native ไวกิ้งนอร์ส folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ นอต็อดเดน',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Notodden.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
