        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-new-orleans-15-143',
        'มณฑปพระพุทธบาทและรอยจารึกธรรม นิวออร์ลีนส์ (ครีโอลวูดู)',
        'The Sacred Footprint and Scripture Shrine of New Orleans (ครีโอลวูดู)',
        'sacred',
        'ลุยเซียนา (สหรัฐอเมริกา)',
        'Louisiana (United States)',
        'นิวออร์ลีนส์',
        'New Orleans',
        29.9511,
        -90.0865,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ลุยเซียนา (สหรัฐอเมริกา) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ครีโอลวูดู เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Louisiana (United States), serving as the spiritual heart of ancestral ครีโอลวูดู heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ลุยเซียนา (สหรัฐอเมริกา) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Louisiana (United States), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน นิวออร์ลีนส์',
        'Remove footwear and maintain silence within the inner terrace of New Orleans.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"มณฑปพระพุทธบาทและรอยจารึกธรรม นิวออร์ลีนส์ (ครีโอลวูดู)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
