        -90.0865,
        'whisper',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง ลุยเซียนา (สหรัฐอเมริกา) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ครีโอลวูดู ใน นิวออร์ลีนส์',
        'A legendary monumental marvel in Louisiana (United States). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ครีโอลวูดู engineers in New Orleans.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ ลุยเซียนา (สหรัฐอเมริกา) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Louisiana (United States), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ นิวออร์ลีนส์',
        'Do not deface, carve, or displace ancient stones in New Orleans.',
        'https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg","title":"ถ้ำภาพเขียนสีโบราณหมื่นปี นิวออร์ลีนส์ (ครีโอลวูดู)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=7PYLVshtJm0","title":"โบราณสถานและมหัศจรรย์แห่งโลกโบราณ","thumbnail":"https://i.ytimg.com/vi/7PYLVshtJm0/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-taos-15-144',
        'วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ เตาส์ (ปูเอโบล)',
        'The Crystal Vihara and Consecrated Icon of Taos (ปูเอโบล)',
        'sacred',
        'นิวเม็กซิโก (สหรัฐอเมริกา)',
        'New Mexico (United States)',
        'เตาส์',
        'Taos',
        36.4222,
        -105.5431,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน นิวเม็กซิโก (สหรัฐอเมริกา) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว ปูเอโบล เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of New Mexico (United States), serving as the spiritual heart of ancestral ปูเอโบล heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค นิวเม็กซิโก (สหรัฐอเมริกา) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in New Mexico (United States), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน เตาส์',
        'Remove footwear and maintain silence within the inner terrace of Taos.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"วิหารแก้วศรัทธาและพระพุทธปฏิมาโบราณ เตาส์ (ปูเอโบล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
