        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-taos-15-144',
        'อมนุษย์กรงเล็บเคียวแห่งหมอกหนาว เตาส์ (ปูเอโบล)',
        'The Razor-Clawed Mist Chimera of Taos (ปูเอโบล)',
        'monster',
        'นิวเม็กซิโก (สหรัฐอเมริกา)',
        'New Mexico (United States)',
        'เตาส์',
        'Taos',
        36.4222,
        -105.5431,
        'creepy_wind',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน นิวเม็กซิโก (สหรัฐอเมริกา) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ เตาส์',
        'Eyewitness reports of a formidable cryptid stalking New Mexico (United States). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Taos.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว ปูเอโบล ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native ปูเอโบล folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ เตาส์',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Taos.',
        'https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg","title":"อมนุษย์กรงเล็บเคียวแห่งหมอกหนาว เตาส์ (ปูเอโบล)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=xo_fMcSLp7Q","title":"สัตว์ลึกลับแห่งพงไพรและสายน้ำโบราณ","thumbnail":"https://i.ytimg.com/vi/xo_fMcSLp7Q/hqdefault.jpg"}]'
      );

