INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-olympic-15-145',
        'เงาไร้หน้าที่บานหน้าต่างค่ำคืน โอลิมปิก (แปซิฟิกนอร์ทเวสต์)',
        'The Faceless Window Silhouette of Olympic (แปซิฟิกนอร์ทเวสต์)',
        'ghost',
        'วอชิงตัน (สหรัฐอเมริกา)',
        'Washington (United States)',
        'โอลิมปิก',
        'Olympic',
        47.8321,
        -123.6344,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น วอชิงตัน (สหรัฐอเมริกา) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ โอลิมปิก',
        'A chilling paranormal account from Washington (United States). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Olympic.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว แปซิฟิกนอร์ทเวสต์ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of แปซิฟิกนอร์ทเวสต์ oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ โอลิมปิก',
        'Never whistle or look back if hearing whispers along twilight pathways in Olympic.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"เงาไร้หน้าที่บานหน้าต่างค่ำคืน โอลิมปิก (แปซิฟิกนอร์ทเวสต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-olympic-15-145',
        'ปีศาจจำแลงร่างล่อลวงคนเดินทาง โอลิมปิก (แปซิฟิกนอร์ทเวสต์)',
        'The Deceptive Shapeshifting Stalker of Olympic (แปซิฟิกนอร์ทเวสต์)',
        'monster',
        'วอชิงตัน (สหรัฐอเมริกา)',
        'Washington (United States)',
        'โอลิมปิก',
        'Olympic',
        47.8321,
        -123.6344,
        'whisper',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน วอชิงตัน (สหรัฐอเมริกา) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ โอลิมปิก',
        'Eyewitness reports of a formidable cryptid stalking Washington (United States). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Olympic.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว แปซิฟิกนอร์ทเวสต์ ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native แปซิฟิกนอร์ทเวสต์ folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ โอลิมปิก',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Olympic.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"ปีศาจจำแลงร่างล่อลวงคนเดินทาง โอลิมปิก (แปซิฟิกนอร์ทเวสต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
