      ) VALUES (
        'pin-curse-olympic-15-145',
        'อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป โอลิมปิก (แปซิฟิกนอร์ทเวสต์)',
        'The Spectral Vessel Curse of Olympic (แปซิฟิกนอร์ทเวสต์)',
        'curse',
        'วอชิงตัน (สหรัฐอเมริกา)',
        'Washington (United States)',
        'โอลิมปิก',
        'Olympic',
        47.8321,
        -123.6344,
        'water_spirit',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง วอชิงตัน (สหรัฐอเมริกา) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน โอลิมปิก',
        'A grim cautionary curse chronicle from Washington (United States). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Olympic.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว แปซิฟิกนอร์ทเวสต์ เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of แปซิฟิกนอร์ทเวสต์, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ โอลิมปิก',
        'Never remove stones, relics, or votive offerings from Olympic.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์เรือวิญญาณและกะลาสีต้องสาป โอลิมปิก (แปซิฟิกนอร์ทเวสต์)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
