      ) VALUES (
        'pin-sacred-valladolid-15-146',
        'พระธาตุยอดเขาพันยอด บายาโดลิด (มายาโบราณ)',
        'The Thousand-Spire Mountain Pagoda of Valladolid (มายาโบราณ)',
        'sacred',
        'ยูกาตัน (เม็กซิโก)',
        'Yucatan (Mexico)',
        'บายาโดลิด',
        'Valladolid',
        20.7344,
        -88.1867,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน ยูกาตัน (เม็กซิโก) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว มายาโบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Yucatan (Mexico), serving as the spiritual heart of ancestral มายาโบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค ยูกาตัน (เม็กซิโก) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Yucatan (Mexico), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน บายาโดลิด',
        'Remove footwear and maintain silence within the inner terrace of Valladolid.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"พระธาตุยอดเขาพันยอด บายาโดลิด (มายาโบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

