INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-legend-monte-alban-15-147',
        'ยอดผาโทรลล์และรอยเท้าบรรพชนยักษ์ มอนเตอัลบัน (ซาโปเทก)',
        'The Petrified Giant Cliffs of Monte Alban (ซาโปเทก)',
        'legend',
        'โออาฮากา (เม็กซิโก)',
        'Oaxaca (Mexico)',
        'มอนเตอัลบัน',
        'Monte Alban',
        16.9989,
        -96.8128,
        'creepy_wind',
        'มรดกตำนานและโบราณสถานอันยิ่งใหญ่แห่ง โออาฮากา (เม็กซิโก) สร้างความอัศจรรย์ใจแก่นักโบราณคดีและผู้มาเยือนด้วยความประณีตของก้อนหินมหึมาและการจัดวางที่สอดคล้องกับดวงดาวในจักรวาล สะท้อนภูมิปัญญาอันเร้นลับของชาว ซาโปเทก ใน มอนเตอัลบัน',
        'A legendary monumental marvel in Oaxaca (Mexico). Archaeoastronomers and travelers marvel at colossal stone architecture aligning with celestial equinoxes, testifying to the sophisticated lost knowledge of ancestral ซาโปเทก engineers in Monte Alban.',
        'สืบทอดผ่านวรรณกรรมมุขปาฐะและร่องรอยโบราณคดีของ โออาฮากา (เม็กซิโก) เป็นหลักฐานชิ้นเอกถึงอารยธรรมรุ่งเรืองในอดีตที่ยังคงทิ้งปริศนาไว้ให้คนรุ่นหลังค้นหา',
        'Preserved across oral epics and excavated strata in Oaxaca (Mexico), representing an indelible testament to ancient cultural zenith and architectural mastery.',
        'ห้ามขีดเขียน ทำลาย หรือเคลื่อนย้ายแท่งหินโบราณในบริเวณ มอนเตอัลบัน',
        'Do not deface, carve, or displace ancient stones in Monte Alban.',
        'https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg","title":"ยอดผาโทรลล์และรอยเท้าบรรพชนยักษ์ มอนเตอัลบัน (ซาโปเทก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=sB7nFq5K_3M","title":"สารคดี อารยธรรมและตำนานโบราณ","thumbnail":"https://i.ytimg.com/vi/sB7nFq5K_3M/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-sacred-valley-15-148',
        'มหารัตนเจดีย์แห่งมโนธรรม หุบเขาศักดิ์สิทธิ์ (อินคา)',
        'The Great Jeweled Pagoda of Sacred Valley (อินคา)',
        'sacred',
        'กุสโก (เปรู)',
        'Cusco (Peru)',
        'หุบเขาศักดิ์สิทธิ์',
        'Sacred Valley',
        -13.3633,
        -72.0833,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน กุสโก (เปรู) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อินคา เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Cusco (Peru), serving as the spiritual heart of ancestral อินคา heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค กุสโก (เปรู) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Cusco (Peru), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน หุบเขาศักดิ์สิทธิ์',
        'Remove footwear and maintain silence within the inner terrace of Sacred Valley.',
        'https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg","title":"มหารัตนเจดีย์แห่งมโนธรรม หุบเขาศักดิ์สิทธิ์ (อินคา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=XltaT0E4snA","title":"สารคดี พุทธศาสนสถานและโบราณสถานศักดิ์สิทธิ์","thumbnail":"https://i.ytimg.com/vi/XltaT0E4snA/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-ghost-sacred-valley-15-148',
        'วิญญาณคนเฝ้าประภาคารผู้ล่วงลับ หุบเขาศักดิ์สิทธิ์ (อินคา)',
        'The Restless Keeper of Sacred Valley (อินคา)',
        'ghost',
        'กุสโก (เปรู)',
        'Cusco (Peru)',
        'หุบเขาศักดิ์สิทธิ์',
        'Sacred Valley',
        -13.3633,
        -72.0833,
        'creepy_wind',
        'เรื่องเล่าสยองขวัญประจำถิ่น กุสโก (เปรู) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ หุบเขาศักดิ์สิทธิ์',
        'A chilling paranormal account from Cusco (Peru). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Sacred Valley.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว อินคา ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of อินคา oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ หุบเขาศักดิ์สิทธิ์',
        'Never whistle or look back if hearing whispers along twilight pathways in Sacred Valley.',
        'https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg","title":"วิญญาณคนเฝ้าประภาคารผู้ล่วงลับ หุบเขาศักดิ์สิทธิ์ (อินคา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=LbCWDUZhSFc","title":"ปริศนาดวงวิญญาณและคฤหาสน์ต้องห้าม","thumbnail":"https://i.ytimg.com/vi/LbCWDUZhSFc/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-monster-sacred-valley-15-148',
        'สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง หุบเขาศักดิ์สิทธิ์ (อินคา)',
        'The Night Livestock Stalker of Sacred Valley (อินคา)',
        'monster',
        'กุสโก (เปรู)',
        'Cusco (Peru)',
        'หุบเขาศักดิ์สิทธิ์',
        'Sacred Valley',
        -13.3633,
        -72.0833,
        'jungle_curse',
        'บันทึกการเผชิญหน้ากับสิ่งมีชีวิตลี้ลับเหนือธรรมชาติใน กุสโก (เปรู) สรีระกำยำน่าสะพรึงกลัว ดวงตาสะท้อนแสงวาวโรจน์ในความมืด กลิ่นสาบสัตว์ป่ารุนแรง และพละกำลังมหาศาลที่ทิ้งร่องรอยกรงเล็บบนเปลือกไม้และรอยพิมพ์เท้าขนาดใหญ่ในแถบ หุบเขาศักดิ์สิทธิ์',
        'Eyewitness reports of a formidable cryptid stalking Cusco (Peru). Witnesses describe glowing tapetal eyes, pungent feral musk, and immense physical strength leaving deep tracks and claw lacerations across Sacred Valley.',
        'เป็นส่วนหนึ่งของนิทานปรัมปราและตำนานพรานป่าของชาว อินคา ที่สะท้อนความยำเกรงต่อพลังลึกลับของธรรมชาติที่ยังไม่ถูกสำรวจ',
        'Rooted in native อินคา folklore, reflecting primeval reverence for uncharted wilderness apex predators that evade modern classification.',
        'ห้ามตามรอยสัตว์ป่าแปลกหน้าเข้าไปในดงทึบหลังพระอาทิตย์ตกดินแถบ หุบเขาศักดิ์สิทธิ์',
        'Never follow unfamiliar predator tracks into deep forest after sunset in Sacred Valley.',
        'https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg","title":"สัตว์ร้ายดูดเลือดแห่งทุ่งรกร้าง หุบเขาศักดิ์สิทธิ์ (อินคา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=8W-DjTLd0mo","title":"สารคดี สัตว์ประหลาดในตำนานและสิ่งลี้ลับ","thumbnail":"https://i.ytimg.com/vi/8W-DjTLd0mo/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
        lat, lng, sound_preset, story_th, story_en, folklore_history_th, folklore_history_en,
        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-curse-sacred-valley-15-148',
        'คำสาปสะพานมรณะและลางบอกเหตุ หุบเขาศักดิ์สิทธิ์ (อินคา)',
        'The Cursed Bridge Omen of Sacred Valley (อินคา)',
        'curse',
        'กุสโก (เปรู)',
        'Cusco (Peru)',
        'หุบเขาศักดิ์สิทธิ์',
        'Sacred Valley',
        -13.3633,
        -72.0833,
        'creepy_wind',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง กุสโก (เปรู) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน หุบเขาศักดิ์สิทธิ์',
        'A grim cautionary curse chronicle from Cusco (Peru). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Sacred Valley.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว อินคา เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of อินคา, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ หุบเขาศักดิ์สิทธิ์',
        'Never remove stones, relics, or votive offerings from Sacred Valley.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"คำสาปสะพานมรณะและลางบอกเหตุ หุบเขาศักดิ์สิทธิ์ (อินคา)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

