      ) VALUES (
        'pin-sacred-salvador-15-149',
        'มหาวิหารแห่งสันติภาพและศรัทธา ซัลวาดอร์ (กานดงเบล)',
        'The Grand Peace Cathedral of Salvador (กานดงเบล)',
