        'Aswan (Egypt)',
        'เกาะฟิเล',
        'Philae Island',
        24.0253,
        32.8692,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน อัสวาน (อียิปต์) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อียิปต์โบราณ เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Aswan (Egypt), serving as the spiritual heart of ancestral อียิปต์โบราณ heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค อัสวาน (อียิปต์) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Aswan (Egypt), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน เกาะฟิเล',
        'Remove footwear and maintain silence within the inner terrace of Philae Island.',
        'https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg","title":"มหาเจดีย์บรมธาตุศักดิ์สิทธิ์ เกาะฟิเล (อียิปต์โบราณ)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=0kKCcsPQekY","title":"เสน่ห์วัดไทย ปฐมเจดีย์และเทวสถานโบราณ","thumbnail":"https://i.ytimg.com/vi/0kKCcsPQekY/hqdefault.jpg"}]'
      );

