        'A chilling paranormal account from Northern Territory (Australia). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Kakadu.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว อะบอริจินดรีมไทม์ ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
