      ) VALUES (
        'pin-curse-pua-16-157',
        'อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม ปัว (ล้านนาตะวันออก)',
        'The Fatal Melody Hex of Pua (ล้านนาตะวันออก)',
        'curse',
        'น่าน (ไทย)',
        'Nan (Thailand)',
        'ปัว',
        'Pua',
        19.1764,
        100.9017,
        'whisper',
        'เรื่องเล่าอาถรรพ์และคำสาปโบราณแห่ง น่าน (ไทย) ผู้ใดที่พยายามลบหลู่ ขโมยวัตถุโบราณ หรือละเมิดข้อห้ามศักดิ์สิทธิ์ มักต้องเผชิญกับชุดเหตุการณ์โชคร้ายอย่างไม่อาจหลีกเลี่ยง บรรยากาศรอบพื้นที่จะหนักอึ้งและมีเสียงเตือนลี้ลับใน ปัว',
        'A grim cautionary curse chronicle from Nan (Thailand). Those who desecrate sacred thresholds or tamper with forbidden relics face catastrophic misfortune and oppressive psychic heaviness throughout Pua.',
        'บันทึกไว้ในตำนานคดีความลี้ลับของชาว ล้านนาตะวันออก เป็นบทเรียนเตือนสติว่าอำนาจมืดหรือแรงอาฆาตในอดีตไม่ใช่สิ่งที่จะท้าทายได้โดยปราศจากผลลัพธ์',
        'Documented in ancestral annals of ล้านนาตะวันออก, serving as an enduring moral reminder against hubris and the violation of spiritual sanctuaries.',
        'ห้ามหยิบจับหรือขโมยเศษหิน วัตถุโบราณ หรือของเซ่นไหว้ออกจากพื้นที่ ปัว',
        'Never remove stones, relics, or votive offerings from Pua.',
        'https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg","title":"อาถรรพ์บทเพลงและเสียงดนตรีต้องห้าม ปัว (ล้านนาตะวันออก)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=TbB9KfaRq70","title":"อาถรรพ์วัตถุต้องคำสาปและโศกนาฏกรรม","thumbnail":"https://i.ytimg.com/vi/TbB9KfaRq70/hqdefault.jpg"}]'
      );

