        'pin-legend-pua-16-157',
        'ยอดผาโทรลล์และรอยเท้าบรรพชนยักษ์ ปัว (ล้านนาตะวันออก)',
        'The Petrified Giant Cliffs of Pua (ล้านนาตะวันออก)',
