        taboos_th, taboos_en, image_url, views_count, is_published, gallery_media
      ) VALUES (
        'pin-sacred-khong-chiam-16-159',
        'มหาวิหารแห่งสันติภาพและศรัทธา โขงเจียม (อีสานริมโขง)',
        'The Grand Peace Cathedral of Khong Chiam (อีสานริมโขง)',
        'sacred',
        'อุบลราชธานี (ไทย)',
        'Ubon Ratchathani (Thailand)',
        'โขงเจียม',
        'Khong Chiam',
        15.3497,
        105.4683,
        'temple_bell',
        'ปูชนียสถานศักดิ์สิทธิ์ประจำดินแดน อุบลราชธานี (ไทย) สถิตเป็นศูนย์รวมแห่งศรัทธาของชาว อีสานริมโขง เล่าขานถึงบารมีและปาฏิหาริย์ขององค์พระธาตุและสิ่งศักดิ์สิทธิ์โบราณที่คุ้มครองผู้ประพฤติชอบ ปรากฏกลิ่นหอมของดอกไม้ทิพย์และสายลมอุ่นพัดผ่านยามสนธยา',
        'A venerated holy landmark of Ubon Ratchathani (Thailand), serving as the spiritual heart of ancestral อีสานริมโขง heritage. Believers recount divine luminescent auras and comforting aromas of sandalwood shielding pilgrims from spiritual adversity.',
        'ก่อตั้งขึ้นตามมุขปาฐะโบราณของภูมิภาค อุบลราชธานี (ไทย) เป็นหลักฐานทางประวัติศาสตร์และสถาปัตยกรรมทางศาสนาที่สืบทอดความเชื่อและพิธีกรรมประจำถิ่นมานานหลายศตวรรษ',
        'Preserved across centuries of oral tradition in Ubon Ratchathani (Thailand), standing as an enduring pillar of communal faith and architectural heritage.',
        'ห้ามสวมรองเท้าหรือส่งเสียงเอะอะในลานชั้นในของปูชนียสถาน โขงเจียม',
        'Remove footwear and maintain silence within the inner terrace of Khong Chiam.',
        'https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg","title":"มหาวิหารแห่งสันติภาพและศรัทธา โขงเจียม (อีสานริมโขง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=EE1yv4CRjzY","title":"เปิดประวัติศาสตร์ มหาเจดีย์ศักดิ์สิทธิ์พันปี","thumbnail":"https://i.ytimg.com/vi/EE1yv4CRjzY/hqdefault.jpg"}]'
      );

INSERT OR REPLACE INTO ghost_pins (
        id, title_th, title_en, category, province_th, province_en, district_th, district_en,
