      ) VALUES (
        'pin-ghost-khong-chiam-16-159',
        'เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน โขงเจียม (อีสานริมโขง)',
        'The Midnight Footsteps of Khong Chiam (อีสานริมโขง)',
        'ghost',
        'อุบลราชธานี (ไทย)',
        'Ubon Ratchathani (Thailand)',
        'โขงเจียม',
        'Khong Chiam',
        15.3497,
        105.4683,
        'whisper',
        'เรื่องเล่าสยองขวัญประจำถิ่น อุบลราชธานี (ไทย) ที่พยานผู้สัญจรผ่านยามวิกาลมักพบเห็นร่างโปร่งแสงหรือเงาตะคุ่มปรากฏตัวพร้อมกับอุณหภูมิที่ลดฮวบลงอย่างฉับพลัน เสียงกระซิบแว่วตามสายลมหนาว และความรู้สึกเหมือนถูกจ้องมองจากความมืดมิดของ โขงเจียม',
        'A chilling paranormal account from Ubon Ratchathani (Thailand). Midnight travelers recount diaphanous apparitions accompanied by sudden drops in ambient temperature, eerie disembodied murmurs, and an overwhelming presence lingering in the shadows of Khong Chiam.',
        'ผูกโยงกับโศกนาฏกรรมหรือประวัติศาสตร์โบราณของชาว อีสานริมโขง ที่ถูกเล่าสืบต่อกันมาจากรุ่นสู่รุ่นในฐานะคำเตือนไม่ให้เดินทางสัญจรตามลำพังยามดึก',
        'Anchored in tragic regional lore of อีสานริมโขง oral memory, passed down through generations as a solemn cautionary tale against wandering isolated paths after dark.',
        'ห้ามผิวปากเรียกหรือหันหลังกลับไปมองเมื่อได้ยินเสียงกระซิบในยามค่ำคืนแถบ โขงเจียม',
        'Never whistle or look back if hearing whispers along twilight pathways in Khong Chiam.',
        'https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg',
        0,
        1,
        '[{"type":"image","url":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg","title":"เสียงฝีเท้าลี้ลับแห่งบันไดวนชั้นใต้ดิน โขงเจียม (อีสานริมโขง)"},{"type":"youtube","url":"https://www.youtube.com/watch?v=D0Wzn0_QpG0","title":"ตำนานผีและเรื่องเล่าสยองขวัญรอบโลก","thumbnail":"https://i.ytimg.com/vi/D0Wzn0_QpG0/hqdefault.jpg"}]'
      );

